import{_ as e,o as a,c as o,a6 as n}from"./chunks/framework.DIp0zHSV.js";const u=JSON.parse('{"title":"Installation","description":"Install LCARdS from HACS, add the integration (Home Assistant 2026.10 or newer) and set it up from the LCARdS Config Panel.","frontmatter":{"description":"Install LCARdS from HACS, add the integration (Home Assistant 2026.10 or newer) and set it up from the LCARdS Config Panel."},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1792162559000}'),s={name:"getting-started/installation.md"};function r(i,t,l,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Home Assistant 2026.10 or newer.</strong> LCARdS relies on 2026.10&#39;s dashboard visibility handling and validation library; on older versions the integration logs an error and does not load.</li></ul><p>Something not working after installing? See <a href="./getting-help.html">Getting Help</a>; the LCARdS panel&#39;s Welcome tab has a built-in health check.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><ol><li><a href="#_1-install-via-hacs">Install from HACS</a></li><li><a href="#_2-add-the-integration">Add the LCARdS integration</a></li><li><a href="#_3-first-setup">First setup in the LCARdS panel</a>: create the helpers, then tune alert modes and sounds</li></ol><div class="tip custom-block"><p class="custom-block-title">HA-LCARS Theme Integration</p><p>LCARdS supports and integrates well with <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer"><strong>HA-LCARS themes</strong></a>. Use these two together for the best experience.</p><p>HA-LCARS includes LCARdS theme profiles (<strong>LCARS Picard [LCARdS Red Accent]</strong> and <strong>[LCARdS Blue Accent]</strong>): choose one as your Home Assistant theme and HA&#39;s own screens match your LCARdS cards. See <a href="./../configuration/ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>.</p></div><h2 id="_1-install-via-hacs" tabindex="-1">1. Install via HACS <a class="header-anchor" href="#_1-install-via-hacs" aria-label="Permalink to &quot;1. Install via HACS&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=snootched&amp;repository=LCARdS&amp;category=integration" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Open in HACS"></a></p><ol><li>Open <strong>HACS</strong> in Home Assistant</li><li>Go to <strong>Integrations</strong> and search for <strong>LCARdS</strong></li><li>Click <strong>Download</strong> and confirm</li><li><strong>Restart Home Assistant</strong>, then <a href="#_2-add-the-integration">add the integration</a>.</li></ol><h3 id="manual-installation" tabindex="-1">Manual Installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual Installation&quot;">​</a></h3><details><summary>Manual installation (unmanaged updates)</summary><ol><li>Download <code>lcards.zip</code> from the <a href="https://github.com/snootched/lcards/releases/latest" target="_blank" rel="noreferrer">latest GitHub release</a></li><li>Extract the contents into <code>config/custom_components/lcards/</code> (the directory should contain <code>manifest.json</code> and <code>__init__.py</code> directly, not a nested <code>lcards/lcards/</code> folder)</li><li><strong>Restart Home Assistant</strong>, then <a href="#_2-add-the-integration">add the integration</a>.</li></ol></details><div class="info custom-block"><p class="custom-block-title">Using <code>custom:layout-card</code>?</p><p>LCARdS has its own <a href="./../cards/layout-card/">Layout Card</a>, which fixes the sizing and margin problems LCARdS cards have inside <code>custom:layout-card</code> and adds a visual editor. Moving over is a one-line change: see <a href="./../cards/common.html#sizing-inside-custom-layout-card">Sizing inside <code>custom:layout-card</code></a>.</p></div><h2 id="_2-add-the-integration" tabindex="-1">2. Add the integration <a class="header-anchor" href="#_2-add-the-integration" aria-label="Permalink to &quot;2. Add the integration&quot;">​</a></h2><p>Go to <strong>Settings &gt; Devices &amp; services &gt; Add integration</strong> and pick <strong>LCARdS</strong>. The integration adds the <strong>LCARdS Config</strong> panel to the sidebar and loads the cards on every dashboard. Its options are listed under <a href="#integration-options">Integration options</a>.</p><h2 id="_3-first-setup" tabindex="-1">3. First setup <a class="header-anchor" href="#_3-first-setup" aria-label="Permalink to &quot;3. First setup&quot;">​</a></h2><p>Open <strong>LCARdS Config</strong> in the sidebar. The <strong>Welcome</strong> tab walks you through the same steps:</p><ol><li><strong>Create the helpers.</strong> In the <strong>Helpers</strong> tab, click <strong>Create All Helpers</strong>. LCARdS keeps alert mode, sound and sizing settings in Home Assistant helpers, and several features (alert mode, the alert overlay, sounds) need them. Do this first.</li><li><strong>Pick your alert colours</strong> (optional). The <strong>Alert Mode Lab</strong> in <strong>Theme Studio</strong> sets how each alert mode recolours your dashboards. See <a href="./../configuration/alert-mode-lab.html">Alert Mode Lab</a>.</li><li><strong>Set up sounds</strong> (optional). The <strong>Sounds</strong> tab turns sounds on, picks a sound scheme and sets volumes. See <a href="./../configuration/sounds.html">Sound Configuration</a>.</li><li><strong>Choose your HA-LCARS theme</strong> (recommended), ideally one of the LCARdS profiles HA-LCARS includes. See <a href="./../configuration/ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>.</li></ol><p>Then check the setup: <strong>Welcome &gt; Support &amp; system info</strong> runs a health check (versions, browser cache, card-mod leftovers).</p><p>The <a href="./../configuration/">Configuration</a> section covers every panel tab in detail.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./building-dashboards.html">Build a dashboard</a></strong>: pick cards and lay out your first LCARS screen.</li><li><strong><a href="./dashboard-gallery.html">Browse the gallery</a></strong>: start from a complete dashboard.</li><li>Stuck? See <strong><a href="./getting-help.html">Getting Help</a></strong>.</li></ul><h2 id="integration-options" tabindex="-1">Integration options <a class="header-anchor" href="#integration-options" aria-label="Permalink to &quot;Integration options&quot;">​</a></h2><p><strong>Settings &gt; Devices &amp; services &gt; LCARdS &gt; Configure</strong>. Changes take effect immediately; no restart needed.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Show sidebar panel</td><td>On</td><td>Display the LCARdS Config entry in the Home Assistant sidebar. Disable if you prefer a cleaner sidebar; the integration stays active and all cards continue to work.</td></tr><tr><td>Sidebar Title</td><td>LCARdS Config</td><td>Customizable title for the sidebar entry.</td></tr><tr><td>Sidebar Icon</td><td><code>mdi:space-invaders</code></td><td>Customizable icon for the sidebar entry.</td></tr><tr><td>Log Level</td><td><code>warn</code></td><td>Default logging level for all cards. <code>debug</code>, <code>trace</code> are very verbose: only use them for deep troubleshooting.</td></tr><tr><td>Enable Preview Features</td><td><code>false</code></td><td>Unlocks features that are still under active development. These may change during development - Please provide your feedback, discuss or get help on GitHub Issues and Discussions.</td></tr></tbody></table><p>If you don&#39;t want the panel in the sidebar all the time, turn <strong>Show sidebar panel</strong> off; it can be turned back on at any time.</p>',26)])])}const p=e(s,[["render",r]]);export{u as __pageData,p as default};
